@startuml

abstract class Property {
  + code : string
  + address : string
  + zip_code : string
  + city : string
  + area : int
  + get_property_details() : string
}

class Garage extends Property {
  + parking_spaces : int
}

class Apartment extends Property {
  + rooms : int
  + bathrooms : int
}

class Villa extends Apartment {
  + garden_size : int
}

class Agency {
  + search(key : string)
}

Agency "1" -- "*" Property : manages

@enduml

